param([string]$AppsRoot='pages/apps') $root=Split-Path -Parent $PSScriptRoot; $appsAbs=Join-Path $root $AppsRoot; $files=Get-ChildItem -Path $appsAbs -Filter 'index.html' -Recurse -File; foreach($f in $files){ $txt=Get-Content -Raw -Path $f.FullName; if($txt -notmatch 'pages/apps/_ui/tokens.css'){ $txt=$txt -replace '(<head[^>]*>)','`$1`n<link rel="stylesheet" href="/pages/apps/_ui/tokens.css">'; [IO.File]::WriteAllText($f.FullName,$txt,[Text.Encoding]::UTF8); Write-Host "Injected tokens.css into $($f.FullName)" } }